'use strict';
const KEY='wordgrove.v1',DAY=86400000,INTERVALS=[10/1440,1,3,7,21,60];
const seeds=[['serendipity','意外發現美好事物的機緣','Finding this little bookshop was pure serendipity.'],['resilient','有韌性的；能恢復的','Plants can be surprisingly resilient.'],['flourish','茁壯成長；蓬勃發展','Small ideas can flourish with a little care.'],['tranquil','寧靜的；平和的','We spent a tranquil afternoon by the lake.'],['curiosity','好奇心','Curiosity leads us to new discoveries.'],['embrace','擁抱；欣然接受','Learn to embrace new experiences.'],['wander','漫步；閒逛','We love to wander through the old town.'],['nurture','培育；滋養','Good habits nurture a healthy mind.'],['abundant','豐富的；充裕的','The garden receives abundant sunlight.'],['perspective','觀點；看法','Travel can offer a fresh perspective.'],['subtle','微妙的；細膩的','There is a subtle difference between the two.'],['cherish','珍惜；珍愛','Cherish the moments you share with friends.'],['venture','冒險；大膽前往','They decided to venture into the forest.'],['genuine','真誠的；真正的','Her smile was warm and genuine.'],['cultivate','培養；耕作','Reading helps cultivate the imagination.'],['vivid','鮮明的；生動的','She has vivid memories of her childhood.'],['deliberate','深思熟慮的；刻意的','Make a deliberate choice to slow down.'],['thrive','茁壯成長；興旺','These flowers thrive in warm weather.'],['replenish','補充；補滿','A good night’s sleep can replenish your energy.'],['versatile','多才多藝的；多用途的','This versatile tool is useful in the kitchen.'],['gratitude','感激；感謝','She expressed her gratitude with a letter.'],['bloom','開花；盛開','The cherry trees bloom in spring.'],['consistent','持續的；一致的','Consistent practice makes a difference.'],['reflect','反思；映照','Take a moment to reflect on your progress.']];
const freshWord=(word,meaning,example='')=>({id:crypto.randomUUID(),word,meaning,example,stage:-1,due:0,reviews:0,last:0});
let data={words:seeds.map(w=>freshWord(...w)),logs:[]},storageOK=true;
try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(!validData(parsed))throw Error('invalid');data=parsed;}}catch(e){storageOK=false;}
let currentPage='overview',session=null,revealed=false,query='',filter='all',toastTimer;
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function validData(d){return d&&Array.isArray(d.words)&&d.words.length<=10000&&Array.isArray(d.logs)&&d.logs.every(l=>Number.isFinite(l.time)&&['again','hard','good','easy'].includes(l.rating))&&d.words.every(w=>w&&typeof w.id==='string'&&typeof w.word==='string'&&w.word.trim()&&w.word.length<=80&&typeof w.meaning==='string'&&w.meaning.trim()&&w.meaning.length<=180&&typeof w.example==='string'&&w.example.length<=400&&Number.isInteger(w.stage)&&w.stage>=-1&&w.stage<=5&&Number.isFinite(w.due)&&w.due>=0&&Number.isInteger(w.reviews)&&w.reviews>=0&&Number.isFinite(w.last))&&new Set(d.words.map(w=>w.id)).size===d.words.length;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true;}catch(e){storageOK=false;toast('瀏覽器無法儲存，請匯出備份以保留進度。');}$('.local-label').innerHTML='<span class="status-dot"></span> '+(storageOK?'進度保存在這個瀏覽器':'無法儲存，請匯出備份');}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function dayKey(t){const d=new Date(t);return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`;}
function stats(){const now=Date.now(),learned=data.words.filter(w=>w.stage>=0),mastered=learned.filter(w=>w.stage>=4),due=learned.filter(w=>w.due<=now),today=data.logs.filter(l=>dayKey(l.time)===dayKey(now));let streak=0,d=new Date();const days=new Set(data.logs.map(l=>dayKey(l.time)));if(!days.has(dayKey(d)))d.setDate(d.getDate()-1);while(days.has(dayKey(d))){streak++;d.setDate(d.getDate()-1);}return{learned,mastered,due,today,streak};}
const stageLabel=w=>w.stage<0?'尚未學習':w.stage>=4?'已熟記':'記憶養成中';
function dueLabel(w){if(w.stage<0)return '等待第一次學習';const delta=w.due-Date.now();if(delta<=0)return '現在可以複習';if(delta<3600000)return `${Math.ceil(delta/60000)} 分鐘後`;if(delta<DAY)return `${Math.ceil(delta/3600000)} 小時後`;return `${Math.ceil(delta/DAY)} 天後`;}
function greeting(){const h=new Date().getHours();return h<11?'早安':h<18?'午安':'晚安';}
function statsHTML(){const s=stats();return `<div class="stats">${[['單字庫總數',data.words.length,'個','▤','包含尚未學習的單字'],['已學習單字',s.learned.length,'個','♧','完成至少一次回想'],['已熟記單字',s.mastered.length,'個','✧','複習間隔達 21 天以上'],['連續學習',s.streak,'天','☼',s.today.length?'今天已留下學習足跡':'今天也種下一點進步']].map(([label,n,u,icon,note])=>`<div class="stat"><div class="stat-head">${label}<span>${icon}</span></div><div class="stat-value">${n}<small>${u}</small></div><div class="stat-note">${note}</div></div>`).join('')}</div>`;}
const plant=`<svg class="hero-art" viewBox="0 0 230 200" aria-hidden="true"><ellipse cx="122" cy="182" rx="79" ry="8" fill="#d7deca"/><path d="M94 126h60l-9 50q-18 12-42 0z" fill="#cdb798"/><path d="M90 125q32-10 68 0v9H90z" fill="#d6c2a6"/><path d="M124 127q-1-52 9-99M127 91Q95 75 88 49M129 64q30-7 39-30" fill="none" stroke="#789366" stroke-width="3"/><path d="M129 59Q108 13 139 13q23 28-10 46" fill="#9aae87"/><path d="M126 98Q80 100 72 68q40-12 54 30" fill="#a7b997"/><path d="M130 80q41 7 51-23-35-16-51 23" fill="#829e71"/><path d="M134 43q33-7 30-33-32 2-30 33" fill="#a7b795"/><path d="M120 123q-34-1-39-26 30-3 39 26" fill="#829b70"/><path d="M177 132l7-8 7 8M184 120v18" fill="none" stroke="#a6b494"/><circle cx="64" cy="40" r="3" fill="#bac6a8"/><path d="M47 135l3-5 3 5-3 5z" fill="#a7b697"/></svg>`;
function memoryChart(){return `<svg class="memory-chart" viewBox="0 0 500 205" role="img" aria-label="記憶概念示意：複習後回想程度上升，隨時間再度下降；不是你的測量結果。"><g stroke="#edf0e7" stroke-dasharray="3 5"><path d="M40 25H480M40 75H480M40 125H480M40 175H480"/></g><g fill="#a5ad9c" font-size="9"><text x="4" y="28">100%</text><text x="12" y="78">70%</text><text x="12" y="128">40%</text><text x="12" y="178">10%</text><text x="37" y="198">初次學習</text><text x="150" y="198">第 1 天</text><text x="270" y="198">第 3 天</text><text x="414" y="198">第 7 天</text></g><path d="M45 30C78 100 120 150 180 164S360 177 475 179" stroke="#cdd2c2" stroke-width="2" fill="none" stroke-dasharray="5 5"/><path d="M45 30Q85 100 155 116L155 31Q210 86 277 95L277 31Q340 68 430 78L430 31Q452 42 475 46" stroke="#829c6c" stroke-width="2.5" fill="none"/><g fill="#fff" stroke="#829c6c" stroke-width="2"><circle cx="155" cy="31" r="4"/><circle cx="277" cy="31" r="4"/><circle cx="430" cy="31" r="4"/></g><g fill="#82946e" font-size="8"><text x="142" y="16">複習</text><text x="264" y="16">複習</text><text x="417" y="16">複習</text></g></svg>`;}
function renderOverview(){const s=stats(),newCount=Math.min(10,data.words.filter(w=>w.stage<0).length),suggested=s.due.length? s.due.slice(0,4):data.words.filter(w=>w.stage<0).slice(0,4);$('#overview').innerHTML=`<div class="heading"><div><span class="eyebrow">A LITTLE EVERY DAY</span><h1>${greeting()}，讓記憶繼續生長 <span class="leaf">♧</span></h1><p class="subtitle">不必一次記住所有單字，每次回想都是進步。</p></div><span class="tag">✦ 跟著自己的節奏</span></div><div class="hero"><div><span class="eyebrow">YOUR DAILY PRACTICE</span><h2>${s.due.length?`有 ${s.due.length} 個單字，等你再次想起。`:newCount?'今天，種下幾個新單字。':'記得留點時間，讓記憶扎根。'}</h2><p>${s.due.length?`先照顧到期的單字，再慢慢累積新的記憶。`:newCount?`準備好 ${newCount} 個新單字，從一次專注的回想開始。`:'目前沒有到期單字，可以到單字庫加入新單字。'}</p><button class="primary" id="startHero">${s.due.length?'開始今日複習':newCount?'開始學習':'新增單字'} <span>↗</span></button></div>${plant}</div>${statsHTML()}<div class="dashboard-grid"><div class="panel"><div class="panel-head"><h2>記憶，需要剛剛好的提醒</h2><div class="chart-legend"><span><i></i>適時複習</span><span><i></i>未複習</span></div></div>${memoryChart()}<div class="chart-caption"><span>↗ 在快忘記時，再回想一次。</span> 這是記憶變化的概念示意，非個人測量曲線。</div></div><div class="panel"><div class="panel-head"><h2>${s.due.length?'等待你回想的單字':'下一批記憶種子'}</h2><button class="text-btn" data-go="library">查看全部 ↗</button></div>${suggested.map(w=>`<div class="word-row"><div class="word-initial">${esc(w.word.charAt(0))}</div><div class="word-text"><strong>${esc(w.word)}</strong><small>${esc(w.meaning)}</small></div><span class="badge">${w.stage<0?'新單字':'待複習'}</span></div>`).join('')||'<div class="empty">單字都安排好了，做得很好。</div>'}</div></div><div class="bottom-note"><span>“ Great things are done by a series of small things. ”</span><span>每天一點點，累積自己的單字森林。</span></div>`;$('#startHero').onclick=()=>s.due.length||newCount?startSession():openAdd();}
function showPage(p){currentPage=p;document.querySelectorAll('.page').forEach(e=>e.classList.toggle('active',e.id===p));document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.page===p));$('#breadcrumb').textContent='你的學習空間 / '+({overview:'學習總覽',review:'今日複習',library:'我的單字庫',progress:'學習足跡'}[p]);render();}
function render(){const s=stats();$('#navDue').textContent=s.due.length;$('#todayDate').textContent=new Date().toLocaleDateString('zh-TW',{year:'numeric',month:'long',day:'numeric',weekday:'short'});if(currentPage==='overview')renderOverview();if(currentPage==='review')renderReview();if(currentPage==='library')renderLibrary();if(currentPage==='progress')renderProgress();}
function startSession(mode='due'){const s=stats();let words=mode==='all'?data.words.filter(w=>w.stage>=0):s.due;if(!words.length)words=data.words.filter(w=>w.stage<0).slice(0,10);if(!words.length){showPage('review');return;}session={ids:words.sort((a,b)=>a.due-b.due).map(w=>w.id),index:0,counts:{again:0,hard:0,good:0,easy:0}};revealed=false;showPage('review');}
function renderReview(){const s=stats();if(!session){const n=Math.min(10,data.words.filter(w=>w.stage<0).length);$('#review').innerHTML=`<div class="heading"><div><span class="eyebrow">TIME TO RECALL</span><h1>和記憶，見個面。</h1><p class="subtitle">先試著回想中文意思，再揭開答案。</p></div></div><div class="review-layout"><div class="flashcard">${plant}<h2 style="font-family:inherit;font-size:24px;margin:5px 0 15px">${s.due.length?`${s.due.length} 個單字到期了`:n?`${n} 個新單字，等你認識`:'今天的複習已完成'}</h2><p class="prompt">${s.due.length?'重溫到期的單字，讓下一次回想更輕鬆。':n?'每次最多學習 10 個新單字，慢慢建立自己的詞庫。':'下次到期時再回來，也可以主動練習已學單字。'}</p>${s.due.length||n?'<button class="primary" id="startReview">開始這次練習 →</button>':s.learned.length?'<button class="primary" id="practiceAll">練習已學單字 →</button>':'<button class="primary" id="addEmpty">加入新單字 ＋</button>'}</div><p class="hint">每次回覆都會影響下次複習時間。請依實際回想情況評分。</p></div>`;if($('#startReview'))$('#startReview').onclick=()=>startSession();if($('#practiceAll'))$('#practiceAll').onclick=()=>startSession('all');if($('#addEmpty'))$('#addEmpty').onclick=openAdd;return;}
if(session.index>=session.ids.length){$('#review').innerHTML=`<div class="review-layout"><div class="flashcard"><div class="summary-check">✓</div><span class="eyebrow">A LITTLE GROWTH, EVERY DAY</span><h2 style="font-family:inherit;font-size:28px">這次的練習完成了。</h2><p class="prompt">完成 ${session.ids.length} 次回想，其中 ${session.counts.good+session.counts.easy} 次記得答案。<br>忘記的單字已安排在 10 分鐘後再次複習。</p><button class="primary" id="doneReview">回到學習總覽 →</button></div><p class="hint">現在休息一下，讓記憶慢慢扎根。</p></div>`;$('#doneReview').onclick=()=>{session=null;showPage('overview');};return;}
const w=data.words.find(w=>w.id===session.ids[session.index]);if(!w){session.index++;renderReview();return;}$('#review').innerHTML=`<div class="heading"><div><span class="eyebrow">ONE WORD AT A TIME</span><h1>把單字，放回記憶裡。</h1></div><button class="text-btn" id="endSession">結束這次練習 ×</button></div><div class="review-layout"><div class="session-top"><span>${w.stage<0?'認識新單字':'記憶複習'}</span><span>${session.index+1} / ${session.ids.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${session.index/session.ids.length*100}%"></div></div><div class="flashcard"><span class="eyebrow">${w.stage<0?'NEW SEED':'GROWING MEMORY'}</span><h2>${esc(w.word)}</h2><button class="speak" id="speakWord" aria-label="播放英文發音">♪</button><div class="sound-status" id="soundStatus"></div>${revealed?`<p class="meaning">${esc(w.meaning)}</p>${w.example?`<p class="example">${esc(w.example)}</p>`:''}`:'<p class="prompt">想一想：這個單字是什麼意思？</p>'}</div><div class="review-actions">${revealed?`<div class="ratings">${[['again','忘記了'],['hard','有點模糊'],['good','記得'],['easy','很熟悉']].map(([r,t])=>`<button data-rate="${r}">${t}<small>${intervalLabel(schedule(w,r).interval)}後複習</small></button>`).join('')}</div>`:'<button class="primary" id="reveal">顯示答案 <span>↵</span></button>'}</div><p class="hint">${revealed?'依照剛才回想的情況選擇，誠實回覆讓安排更適合你。':'先主動回想，再查看答案。按 Enter 或點擊顯示答案。'}</p></div>`;$('#endSession').onclick=()=>{session=null;renderReview();};$('#speakWord').onclick=()=>speak(w.word);if($('#reveal'))$('#reveal').onclick=()=>{revealed=true;renderReview();};document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>rateWord(w,b.dataset.rate));}
function intervalLabel(v){return v<1?`${Math.round(v*1440)} 分鐘`:`${v} 天`;}
function schedule(w,r){let stage=w.stage,interval;if(r==='again'){stage=0;interval=INTERVALS[0];}else if(r==='hard'){stage=Math.max(0,Math.min(stage,1));interval=stage===0?30/1440:1;}else{stage=Math.min(5,Math.max(0,stage)+(r==='easy'?2:1));interval=INTERVALS[stage];}return{stage,interval};}
function rateWord(w,r){if(!revealed)return;revealed=false;const next=schedule(w,r),now=Date.now();Object.assign(w,{stage:next.stage,due:now+next.interval*DAY,reviews:w.reviews+1,last:now});data.logs.push({time:now,rating:r,id:w.id});session.counts[r]++;session.index++;save();render();}
function speak(word){if(!('speechSynthesis'in window)){toast('這個瀏覽器不支援語音播放。');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(word);u.lang='en-US';u.rate=.85;u.onerror=()=>{if($('#soundStatus'))$('#soundStatus').textContent='目前無法播放發音';};speechSynthesis.speak(u);}
function renderLibrary(){const words=data.words.filter(w=>(w.word+' '+w.meaning).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||filter==='new'&&w.stage<0||filter==='learning'&&w.stage>=0&&w.stage<4||filter==='mastered'&&w.stage>=4));$('#library').innerHTML=`<div class="heading"><div><span class="eyebrow">YOUR GROWING COLLECTION</span><h1>我的單字庫</h1><p class="subtitle">每個單字，都是一顆等待發芽的種子。</p></div><button class="primary" id="addWord">＋ 新增單字</button></div><div class="toolbar"><input type="search" id="search" placeholder="搜尋英文單字或中文意思…" aria-label="搜尋單字" value="${esc(query)}"><select id="statusFilter" aria-label="篩選學習狀態">${[['all','全部單字'],['new','尚未學習'],['learning','記憶養成中'],['mastered','已熟記']].map(([v,t])=>`<option value="${v}" ${v===filter?'selected':''}>${t}</option>`).join('')}</select><button class="secondary" id="exportLib">↥ 匯出備份</button><button class="secondary" id="importLib">↧ 匯入備份</button></div><div class="panel"><div class="panel-head"><h2>我的收藏</h2><span class="today-number">${words.length} 個單字</span></div><div class="table-wrap"><table><thead><tr><th>單字 / 意思</th><th>記憶狀態</th><th>下次複習</th><th>回想次數</th><th>操作</th></tr></thead><tbody>${words.map(w=>`<tr><td><span class="table-word">${esc(w.word)}</span><br><small>${esc(w.meaning)}</small></td><td><span class="badge ${w.stage>=4?'mastered':''}">${stageLabel(w)}</span></td><td><small>${dueLabel(w)}</small></td><td>${w.reviews}</td><td><button class="delete" data-delete="${esc(w.id)}" aria-label="刪除 ${esc(w.word)}">刪除</button></td></tr>`).join('')}</tbody></table>${words.length?'':'<div class="empty">沒有符合的單字，換個關鍵字或新增一個吧。</div>'}</div></div><p class="import-info">內建 24 個入門單字；首次使用尚未計入已學習。備份包含單字、複習排程與學習紀錄。</p>`;$('#addWord').onclick=openAdd;$('#exportLib').onclick=exportData;$('#importLib').onclick=()=>$('#importFile').click();$('#search').oninput=e=>{const caret=e.target.selectionStart;query=e.target.value;renderLibrary();$('#search').focus();$('#search').setSelectionRange(caret,caret);};$('#statusFilter').onchange=e=>{filter=e.target.value;renderLibrary();};document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const w=data.words.find(w=>w.id===b.dataset.delete);if(w&&confirm(`刪除「${w.word}」及其學習紀錄？`)){data.words=data.words.filter(x=>x.id!==w.id);data.logs=data.logs.filter(l=>l.id!==w.id);save();render();toast('已刪除單字');}});}
function renderProgress(){const s=stats(),newN=data.words.length-s.learned.length,learning=s.learned.length-s.mastered.length,total=Math.max(1,data.words.length),days=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()+i);const next=new Date(d);next.setDate(next.getDate()+1);return{label:i===0?'今天':`${d.getMonth()+1}/${d.getDate()}`,count:data.words.filter(w=>w.stage>=0&&(i===0?w.due<+next:w.due>=+d&&w.due<+next)).length};}),max=Math.max(1,...days.map(d=>d.count)),recent=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return {label:i===6?'今天':`${d.getMonth()+1}/${d.getDate()}`,count:data.logs.filter(l=>dayKey(l.time)===dayKey(d)).length};}),maxRecent=Math.max(1,...recent.map(d=>d.count));$('#progress').innerHTML=`<div class="heading"><div><span class="eyebrow">WATCH YOUR MEMORY GROW</span><h1>每一點進步，都看得見。</h1><p class="subtitle">記錄你走過的路，也為下一次回想留一點空間。</p></div></div>${statsHTML()}<div class="dashboard-grid"><div class="panel"><div class="panel-head"><h2>最近 7 天的回想</h2><span class="today-number">累計 ${data.logs.length} 次</span></div><div class="schedule">${recent.map(d=>`<div class="day-column"><small>${d.count}</small><div class="bar" style="height:${d.count/maxRecent*135}px"></div><span>${d.label}</span></div>`).join('')}</div><p class="import-info">以評分完成的回想次數計算，同一單字可計入多次。</p></div><div class="panel"><div class="panel-head"><h2>接下來 7 天的複習</h2><span class="today-number">${days.reduce((n,d)=>n+d.count,0)} 個單字</span></div><div class="schedule">${days.map(d=>`<div class="day-column"><small>${d.count}</small><div class="bar" style="height:${d.count/max*135}px;background:#c8b799"></div><span>${d.label}</span></div>`).join('')}</div><p class="import-info">今天包含已逾期單字；隨每次評分更新排程。</p></div></div><div class="panel small-panel"><div class="panel-head"><h2>你的單字森林</h2><span class="today-number">熟記比例 ${Math.round(s.mastered.length/total*100)}%</span></div><div class="breakdown"><div style="width:${s.mastered.length/total*100}%;background:#486c4c"></div><div style="width:${learning/total*100}%;background:#a6b88e"></div><div style="width:${newN/total*100}%;background:#e2e8d7"></div></div><div class="legend-row"><span><i style="background:#486c4c"></i>已熟記 ${s.mastered.length}</span><span><i style="background:#a6b88e"></i>養成中 ${learning}</span><span><i style="background:#e2e8d7"></i>未學習 ${newN}</span></div><p class="progress-info">這裡的「單字量」是你在此單字庫的學習紀錄，並非整體英語詞彙量測驗。<br>依回想表現安排間隔：忘記 10 分鐘、有點模糊 30 分鐘或 1 天；記得則依序延長至 1、3、7、21、60 天。「很熟悉」會多前進一階。間隔達 21 天即標記已熟記，仍會安排複習。</p></div>`;}
function openAdd(){ $('#wordForm').reset();$('#formError').textContent='';$('#wordDialog').showModal();$('#wordInput').focus();}
function exportData(){const blob=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString(),version:1},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`wordgrove-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('已匯出單字與學習紀錄');}
$('#wordForm').onsubmit=e=>{e.preventDefault();const word=$('#wordInput').value.trim(),meaning=$('#meaningInput').value.trim(),example=$('#exampleInput').value.trim();if(!word||!meaning){$('#formError').textContent='請填寫單字與中文意思。';return;}if(data.words.some(w=>w.word.toLowerCase()===word.toLowerCase())){$('#formError').textContent='這個單字已經在你的花園裡了。';return;}data.words.unshift(freshWord(word,meaning,example));save();$('#wordDialog').close();render();toast('已種下一個新單字');};
$('#closeDialog').onclick=()=>$('#wordDialog').close();$('#exportSide').onclick=exportData;
$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error();const incoming=JSON.parse(await f.text());if(!validData(incoming))throw Error();if(confirm(`匯入 ${incoming.words.length} 個單字和 ${incoming.logs.length} 筆學習紀錄？這會取代目前進度，建議先匯出備份。`)){data={words:incoming.words,logs:incoming.logs};session=null;save();render();toast('學習進度已還原');}}catch(err){toast('備份格式不正確，請選擇 Wordgrove 匯出的 JSON 檔案。');}e.target.value='';};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)showPage(b.dataset.go);});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&currentPage==='review'&&session&&!revealed&&$('#reveal')&&!['BUTTON','INPUT','TEXTAREA'].includes(document.activeElement.tagName)){$('#reveal').click();}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});render();if(!storageOK)toast('無法讀取已存進度，請用匯入備份還原，或匯出目前資料。');
